import { Object3D, Mesh, PlaneGeometry, Color } from 'three/webgpu';
import {
	MeshStandardNodeMaterial,
	uvNode,
	mixNode,
	colorNode,
} from 'three/tsl';
import { gsap } from 'gsap';
import { createTextNode } from '@/text';
import { /* primitives can be imported if needed */ } from '@/primitives';

export default function createNode(config, ctx) {
	const root = new Object3D();
	root.position.set(
		(config.position?.x ?? 0),
		(config.position?.y ?? 0),
		(config.position?.z ?? 0)
	);
	root.rotation.set(
		(config.rotation?.x ?? 0),
		(config.rotation?.y ?? 0),
		(config.rotation?.z ?? 0)
	);
	root.scale.set(
		(config.scale?.x ?? 1),
		(config.scale?.y ?? 1),
		(config.scale?.z ?? 1)
	);

	// ------- Grid setup -------
	const tileW = 1.0;
	const tileH = 0.62;
	const gap = 0.25;
	const cols = 3;
	const rows = 2;

	const totalW = cols * tileW + (cols - 1) * gap;
	const totalH = rows * tileH + (rows - 1) * gap;

	const startX = -totalW / 2 + tileW / 2;
	const startY = totalH / 2 - tileH / 2;

	const brandNames = [
		'HODINKEE',
		'MONOCLE',
		'WALLPAPER',
		'ESQUIRE',
		'WIRED',
		'FINANCIAL TIMES',
	];

	const gradientTop = new Color(config.visual.colors.gradientStops[0].hex);
	const gradientBottom = new Color(config.visual.colors.gradientStops[1].hex);

	const tileGeom = new PlaneGeometry(tileW, tileH);
	const tilesData = [];

	for (let r = 0; r < rows; r++) {
		for (let c = 0; c < cols; c++) {
			const idx = r * cols + c;
			const brand = brandNames[idx];

			const x = startX + c * (tileW + gap);
			const y = startY - r * (tileH + gap);

			// ----- Tile material (gradient PBR) -----
			const uv = uvNode();
			const grad = mixNode(
				colorNode(gradientTop),
				colorNode(gradientBottom),
				uv.y
			);
			const tileMat = new MeshStandardNodeMaterial({
				colorNode: grad,
				metalness: 0.5,
				roughness: 0.55,
				clearcoat: 0.2,
				transparent: true,
			});

			const tileMesh = new Mesh(tileGeom, tileMat);
			tileMesh.position.set(x, y + 0.2, 0); // start offset for mount animation
			tileMesh.scale.set(1, 1, 1);
			tileMesh.material.opacity = 0; // start invisible
			root.add(tileMesh);

			// ----- Brand text (MSDF) -----
			const textOpts = {
				text: brand,
				fontSize: config.typography['brand-mark'].fontSize,
				fontWeight: config.typography['brand-mark'].fontWeight,
				letterSpacing: config.typography['brand-mark'].letterSpacing,
				lineHeight: config.typography['brand-mark'].lineHeight,
				color: '#e8ecf2',
				opacity: 0.78,
				align: 'center',
			};

			const textMesh = createTextNode(textOpts, ctx.fontAtlas);
			textMesh.position.set(0, 0, 0.001); // tiny offset to avoid z‑fight
			textMesh.scale.set(0.9, 0.9, 0.9); // fit inside tile
			tileMesh.add(textMesh);

			// Store for mount animation & hover handling
			tilesData.push({
				mesh: tileMesh,
				targetY: y,
				textMaterial: textMesh.material,
			});
		}
	}

	// ------- Kicker text above the grid -------
	const kickerOpts = {
		text: 'AS FEATURED IN',
		fontSize: config.typography.kicker.fontSize,
		fontWeight: config.typography.kicker.fontWeight,
		letterSpacing: config.typography.kicker.letterSpacing,
		lineHeight: config.typography.kicker.lineHeight,
		color: '#e8ecf2',
		opacity: 1,
		align: 'center',
	};
	const kickerMesh = createTextNode(kickerOpts, ctx.fontAtlas);
	const kickerY =
		startY + tileH / 2 + 0.3; // 0.3 units above the top edge of the grid
	kickerMesh.position.set(0, kickerY, 0.01);
	root.add(kickerMesh);

	// ------- Mount stagger animation (fade‑up) -------
	const mountTl = gsap.timeline();
	tilesData.forEach((data, i) => {
		mountTl.to(
			data.mesh.position,
			{
				y: data.targetY,
				duration: 0.5,
				ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
			},
			i * 0.08
		);
		mountTl.to(
			data.mesh.material,
			{
				opacity: 1,
				duration: 0.5,
				ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
			},
			i * 0.08
		);
	});
	mountTl.play();

	// ------- Hover handlers per tile -------
	tilesData.forEach((data) => {
		const hoverEnter = () => {
			gsap.to(data.mesh.position, {
				z: 0.05,
				duration: 0.16,
				ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
			});
			gsap.to(data.textMaterial, {
				opacity: 1.0,
				duration: 0.16,
				ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
			});
		};
		const hoverLeave = () => {
			gsap.to(data.mesh.position, {
				z: 0,
				duration: 0.16,
				ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
			});
			gsap.to(data.textMaterial, {
				opacity: 0.78,
				duration: 0.16,
				ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
			});
		};
		data.mesh.userData.handlers = { hoverEnter, hoverLeave };
	});

	// ------- Cleanup -------
	root.userData.cleanup = () => {
		gsap.killTweensOf(root);
		mountTl.kill();
		tilesData.forEach((data) => {
			gsap.killTweensOf(data.mesh);
			gsap.killTweensOf(data.textMaterial);
			if (data.mesh.geometry) data.mesh.geometry.dispose();
			if (data.mesh.material) data.mesh.material.dispose();
			if (data.textMaterial.map) data.textMaterial.map.dispose();
			if (data.textMaterial) data.textMaterial.dispose();
		});
		if (kickerMesh.geometry) kickerMesh.geometry.dispose();
		if (kickerMesh.material) {
			if (kickerMesh.material.map) kickerMesh.material.map.dispose();
			kickerMesh.material.dispose();
		}
		if (tileGeom) tileGeom.dispose();
	};

	return root;
}
